use std::ffi::CString;

#[repr(C)]
pub struct git_repository { _private: [u8; 0] }

extern "C" {
    fn git_libgit2_init() -> i32;
    fn git_repository_open_ext(
        out: *mut *mut git_repository,
        path: *const i8,
        flags: u32,
        ceiling_dirs: *const i8,
    ) -> i32;
    fn git_error_last() -> *const git_error;
}

#[repr(C)]
pub struct git_error {
    pub message: *const i8,
    pub klass: i32,
}

fn main() {
    unsafe {
        git_libgit2_init();
        let path = CString::new("/tmp").unwrap();
        let mut repo: *mut git_repository = std::ptr::null_mut();
        let res = git_repository_open_ext(&mut repo, path.as_ptr(), 0, std::ptr::null());
        println!("res: {}", res);
        if res != 0 {
            let err = git_error_last();
            if !err.is_null() {
                let msg = std::ffi::CStr::from_ptr((*err).message).to_string_lossy();
                println!("error msg: {}", msg);
            }
        }
    }
}
