use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_uint};

#[repr(C)] pub struct git_repository { _unused: [u8; 0] }
#[repr(C)] pub struct git_reference { _unused: [u8; 0] }
#[repr(C)] pub struct git_reference_iterator { _unused: [u8; 0] }
#[repr(C)] pub struct git_revwalk { _unused: [u8; 0] }
#[repr(C)] pub struct git_commit { _unused: [u8; 0] }
#[repr(C)] pub struct git_object { _unused: [u8; 0] }

#[repr(C)]
#[derive(Copy, Clone, Debug)]
pub struct git_oid {
    pub id: [u8; 20],
}

#[repr(C)]
pub struct git_time {
    pub time: i64,
    pub offset: c_int,
    pub sign: c_char,
}

#[repr(C)]
pub struct git_signature {
    pub name: *const c_char,
    pub email: *const c_char,
    pub when: git_time,
}

extern "C" {
    fn git_libgit2_init() -> c_int;
    fn git_libgit2_shutdown() -> c_int;
    fn git_libgit2_opts(opt: c_int, ...) -> c_int;
    fn git_repository_open_ext(out: *mut *mut git_repository, path: *const c_char, flags: c_uint, ceiling_dirs: *const c_char) -> c_int;
    fn git_repository_free(repo: *mut git_repository);

    fn git_reference_iterator_new(out: *mut *mut git_reference_iterator, repo: *mut git_repository) -> c_int;
    fn git_reference_next(out: *mut *mut git_reference, iter: *mut git_reference_iterator) -> c_int;
    fn git_reference_iterator_free(iter: *mut git_reference_iterator);
    fn git_reference_name(ref_: *const git_reference) -> *const c_char;
    fn git_reference_target(ref_: *const git_reference) -> *const git_oid;
    fn git_reference_is_branch(ref_: *const git_reference) -> c_int;
    fn git_reference_is_tag(ref_: *const git_reference) -> c_int;
    fn git_reference_is_remote(ref_: *const git_reference) -> c_int;
    fn git_reference_peel(out: *mut *mut git_object, ref_: *const git_reference, type_: c_int) -> c_int;
    fn git_reference_free(ref_: *mut git_reference);
    fn git_object_free(obj: *mut git_object);
    fn git_object_id(obj: *const git_object) -> *const git_oid;

    fn git_revwalk_new(out: *mut *mut git_revwalk, repo: *mut git_repository) -> c_int;
    fn git_revwalk_sorting(walk: *mut git_revwalk, sort_mode: c_uint) -> c_int;
    fn git_revwalk_push_glob(walk: *mut git_revwalk, glob: *const c_char) -> c_int;
    fn git_revwalk_push_head(walk: *mut git_revwalk) -> c_int;
    fn git_revwalk_next(out: *mut git_oid, walk: *mut git_revwalk) -> c_int;
    fn git_revwalk_free(walk: *mut git_revwalk);

    fn git_commit_lookup(out: *mut *mut git_commit, repo: *mut git_repository, id: *const git_oid) -> c_int;
    fn git_commit_free(commit: *mut git_commit);
    fn git_commit_summary(commit: *const git_commit) -> *const c_char;
    fn git_commit_author(commit: *const git_commit) -> *const git_signature;
    fn git_commit_committer(commit: *const git_commit) -> *const git_signature;
    fn git_commit_parentcount(commit: *const git_commit) -> c_uint;
    fn git_commit_parent(out: *mut *mut git_commit, commit: *const git_commit, n: c_uint) -> c_int;
    fn git_commit_id(commit: *const git_commit) -> *const git_oid;
}

fn main() {
    unsafe {
        git_libgit2_init();
        let path = CString::new(".").unwrap();
        let mut repo: *mut git_repository = std::ptr::null_mut();
        let res = git_repository_open_ext(&mut repo, path.as_ptr(), 0, std::ptr::null());
        if res == 0 {
            println!("Repo opened successfully!");

            let mut iter: *mut git_reference_iterator = std::ptr::null_mut();
            if git_reference_iterator_new(&mut iter, repo) == 0 {
                let mut ref_: *mut git_reference = std::ptr::null_mut();
                while git_reference_next(&mut ref_, iter) == 0 {
                    let name_ptr = git_reference_name(ref_);
                    let name = CStr::from_ptr(name_ptr).to_string_lossy();
                    let is_b = git_reference_is_branch(ref_);
                    let is_t = git_reference_is_tag(ref_);
                    let is_r = git_reference_is_remote(ref_);
                    println!("Ref: {} (b:{}, t:{}, r:{})", name, is_b, is_t, is_r);
                    git_reference_free(ref_);
                }
                git_reference_iterator_free(iter);
            }

            git_repository_free(repo);
        }
        git_libgit2_shutdown();
    }
}
