                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--max-count <n>' but none was supplied");
                    process::exit(2);
                }
                let val_str = &args[i + 1];
                match val_str.parse::<usize>() {
                    Ok(n) => max_count = Some(n),
                    Err(_) => {
                        eprintln!("Option max-count must be a positive number, but got '{}'", val_str);
                        process::exit(1);
                    }
                }
                i += 1;
            } else if arg == "--color" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--color <color>' but none was supplied");
                    process::exit(2);
                }
                color = args[i + 1].clone();
                if color != "auto" && color != "always" && color != "never" {
                    eprintln!("Unknown color mode '{}'. Supports [auto|always|never].", color);
                    process::exit(1);
                }
                i += 1;
            } else if arg == "--no-color" {
                no_color = true;
            } else if arg == "-w" || arg == "--wrap" {
                let mut wrap_args = Vec::new();
                while i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    // Check if next arg is subcommand like model or help
                    if args[i + 1] == "model" || args[i + 1] == "help" {
