use std::env;
use std::process;

#[derive(Debug, Clone)]
pub enum Subcommand {
    None,
    Model {
        model: Option<String>,
        list: bool,
    },
    Help {
        cmd: Option<String>,
    },
}

#[derive(Debug, Clone)]
pub struct CliArgs {
    pub path: String,
    pub skip_owner_validation: bool,
    pub model: Option<String>,
    pub max_count: Option<usize>,
    pub color: String, // "auto", "always", "never"
    pub no_color: bool,
