                }
                i += 1;
            } else if arg == "--no-color" {
                no_color = true;
            } else if arg == "-w" || arg == "--wrap" {
                let mut wrap_args = Vec::new();
                while i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    // Check if next arg is subcommand like model or help
                    if args[i + 1] == "model" || args[i + 1] == "help" {
                        break;
                    }
                    wrap_args.push(args[i + 1].clone());
                    i += 1;
                }
                if wrap_args.is_empty() {
                    wrap = "auto".to_string();
