cat <<'EOF' > src/args.rs
use std::env;
use std::process;

#[derive(Debug, Clone)]
pub enum Subcommand {
    None,
    Model {
        model: Option<String>,
        list: bool,
    },
    Help {
        cmd: Option<String>,
    },
}

#[derive(Debug, Clone)]
pub struct CliArgs {
    pub path: String,
    pub skip_owner_validation: bool,
    pub model: Option<String>,
    pub max_count: Option<usize>,
    pub color: String, // "auto", "always", "never"
    pub no_color: bool,
    pub wrap: String, // raw wrap string e.g. "auto 0 8" or "none" or "20 0 4"
    pub format: String,
    pub reverse: bool,
    pub local_only: bool,
    pub svg: bool,
    pub debug: bool,
    pub sparse: bool,
    pub style: String,
    pub help: bool,
    pub version: bool,
    pub subcommand: Subcommand,
}

impl CliArgs {
    pub fn parse() -> Self {
        let args: Vec<String> = env::args().collect();
        let mut path = ".".to_string();
        let mut skip_owner_validation = false;
        let mut model = None;
        let mut max_count = None;
        let mut color = "auto".to_string();
        let mut no_color = false;
        let mut wrap = "auto 0 8".to_string();
        let mut format = "oneline".to_string();
        let mut reverse = false;
        let mut local_only = false;
        let mut svg = false;
        let mut debug = false;
        let mut sparse = false;
        let mut style = "normal".to_string();
        let mut help = false;
        let mut version = false;
        let mut subcommand = Subcommand::None;

        let mut i = 1;
        while i < args.len() {
            let arg = &args[i];
            if arg == "-h" {
                print_short_help();
                process::exit(0);
            } else if arg == "--help" {
                print_long_help();
                process::exit(0);
            } else if arg == "-V" || arg == "--version" {
                println!("git-graph 0.7.0");
                process::exit(0);
            } else if arg == "help" {
                if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    let sub = &args[i + 1];
                    if sub == "model" {
                        print_model_help();
                        process::exit(0);
                    }
                }
                print_long_help();
                process::exit(0);
            } else if arg == "model" {
                let mut model_arg = None;
                let mut list_flag = false;
                let mut j = i + 1;
                while j < args.len() {
                    let a = &args[j];
                    if a == "-h" || a == "--help" {
                        print_model_help();
                        process::exit(0);
                    } else if a == "-l" || a == "--list" {
                        list_flag = true;
                    } else if !a.starts_with('-') {
                        if model_arg.is_none() {
                            model_arg = Some(a.clone());
                        }
                    } else {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable model [OPTIONS] [model]\n\nFor more information, try '--help'.", a);
                        process::exit(2);
                    }
                    j += 1;
                }
                subcommand = Subcommand::Model {
                    model: model_arg,
                    list: list_flag,
                };
                break;
            } else if arg == "-p" || arg == "--path" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--path <path>' but none was supplied");
                    process::exit(2);
                }
                path = args[i + 1].clone();
                i += 1;
            } else if arg == "--skip-repo-owner-validation" {
                skip_owner_validation = true;
            } else if arg == "-m" || arg == "--model" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--model <model>' but none was supplied");
                    process::exit(2);
                }
                model = Some(args[i + 1].clone());
                i += 1;
            } else if arg == "-n" || arg == "--max-count" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--max-count <n>' but none was supplied");
                    process::exit(2);
                }
                let val_str = &args[i + 1];
                match val_str.parse::<usize>() {
                    Ok(n) => max_count = Some(n),
                    Err(_) => {
                        eprintln!("Option max-count must be a positive number, but got '{}'", val_str);
                        process::exit(1);
                    }
                }
                i += 1;
            } else if arg == "--color" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--color <color>' but none was supplied");
                    process::exit(2);
                }
                color = args[i + 1].clone();
                if color != "auto" && color != "always" && color != "never" {
                    eprintln!("Unknown color mode '{}'. Supports [auto|always|never].", color);
                    process::exit(1);
                }
                i += 1;
            } else if arg == "--no-color" {
                no_color = true;
            } else if arg == "-w" || arg == "--wrap" {
                let mut wrap_args = Vec::new();
                while i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    // Check if next arg is subcommand like model or help
                    if args[i + 1] == "model" || args[i + 1] == "help" {
                        break;
                    }
                    wrap_args.push(args[i + 1].clone());
                    i += 1;
                }
                if wrap_args.is_empty() {
                    wrap = "auto".to_string();
                } else {
                    wrap = wrap_args.join(" ");
                }
            } else if arg == "-f" || arg == "--format" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--format <format>' but none was supplied");
                    process::exit(2);
                }
                format = args[i + 1].clone();
                i += 1;
            } else if arg == "-r" || arg == "--reverse" {
                reverse = true;
            } else if arg == "-l" || arg == "--local" {
                local_only = true;
            } else if arg == "--svg" {
                svg = true;
            } else if arg == "-d" || arg == "--debug" {
                debug = true;
            } else if arg == "-S" || arg == "--sparse" {
                sparse = true;
            } else if arg == "-s" || arg == "--style" {
                if i + 1 >= args.len() {
                    eprintln!("error: a value is required for '--style <style>' but none was supplied");
                    process::exit(2);
                }
                style = args[i + 1].clone();
                i += 1;
            } else if arg.starts_with('-') {
                // handle flags like -sround or -fm or combined flags like -dS
                if arg.starts_with("-s") && arg.len() > 2 {
                    style = arg[2..].to_string();
                } else if arg.starts_with("-f") && arg.len() > 2 {
                    format = arg[2..].to_string();
                } else if arg.starts_with("-m") && arg.len() > 2 {
                    model = Some(arg[2..].to_string());
                } else if arg.starts_with("-p") && arg.len() > 2 {
                    path = arg[2..].to_string();
                } else if arg.starts_with("-n") && arg.len() > 2 {
                    let val_str = &arg[2..];
                    match val_str.parse::<usize>() {
                        Ok(n) => max_count = Some(n),
                        Err(_) => {
                            eprintln!("Option max-count must be a positive number, but got '{}'", val_str);
                            process::exit(1);
                        }
                    }
                } else {
                    // Check if it's multiple short flags combined e.g. -dS or -rl
                    let chars: Vec<char> = arg[1..].chars().collect();
                    let mut matched_all = true;
                    for c in chars {
                        match c {
                            'r' => reverse = true,
                            'l' => local_only = true,
                            'd' => debug = true,
                            'S' => sparse = true,
                            'h' => help = true,
                            'V' => version = true,
                            _ => {
                                matched_all = false;
                                break;
                            }
                        }
                    }
                    if !matched_all {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.", arg);
                        process::exit(2);
                    }
                }
            } else {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.", arg);
                process::exit(2);
            }
            i += 1;
        }

        CliArgs {
            path,
            skip_owner_validation,
            model,
            max_count,
            color,
            no_color,
            wrap,
            format,
            reverse,
            local_only,
            svg,
            debug,
            sparse,
            style,
            help,
            version,
            subcommand,
        }
    }
}

