use std::fs;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct ModelConfig {
    pub name: String,
    pub persistence: Vec<String>,
    pub order: Vec<String>,
    pub terminal_matches: Vec<(String, Vec<String>)>,
    pub terminal_unknown: Vec<String>,
    pub svg_matches: Vec<(String, Vec<String>)>,
    pub svg_unknown: Vec<String>,
}

pub fn get_models_dir() -> Option<PathBuf> {
    if let Some(config_dir) = dirs::config_dir() {
        let p = config_dir.join("git-graph").join("models");
        if p.exists() && p.is_dir() {
            return Some(p);
        }
    }
    None
}

pub fn list_models() -> Vec<String> {
    if let Some(models_dir) = get_models_dir() {
        let mut result = Vec::new();
        if let Ok(entries) = fs::read_dir(&models_dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("toml") {
                    if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                        result.push(stem.to_string());
                    }
                }
            }
        }
        result
    } else {
        vec!["git-flow".to_string(), "simple".to_string(), "none".to_string()]
    }
}

pub fn load_model(name: &str) -> Result<ModelConfig, String> {
    if let Some(models_dir) = get_models_dir() {
        let toml_path = models_dir.join(format!("{}.toml", name));
        if toml_path.exists() {
            if let Ok(content) = fs::read_to_string(&toml_path) {
                if let Ok(config) = parse_toml_model(name, &content) {
                    return Ok(config);
                }
            }
        }
        let available = list_models().join(", ");
        let dir_str = models_dir.to_string_lossy();
        return Err(format!(
            "ERROR: No branching model named '{}' found in {}\n       Available models are: {}",
            name, dir_str, available
        ));
    }

    // Built-in presets
    match name {
        "git-flow" => Ok(get_builtin_git_flow()),
        "simple" => Ok(get_builtin_simple()),
        "none" => Ok(get_builtin_none()),
        _ => {
            let config_dir_str = dirs::config_dir()
                .map(|p| p.join("git-graph").join("models").to_string_lossy().to_string())
                .unwrap_or_else(|| "/home/agent/.config/git-graph/models".to_string());
            Err(format!(
                "ERROR: No branching model named '{}' found in {}\n       Available models are: git-flow, simple, none",
                name, config_dir_str
            ))
        }
    }
}

fn get_builtin_git_flow() -> ModelConfig {
    ModelConfig {
        name: "git-flow".to_string(),
        persistence: vec![
            "^(master|main|trunk)$".to_string(),
            "^(develop|dev)$".to_string(),
            "^feature.*$".to_string(),
            "^release.*$".to_string(),
            "^hotfix.*$".to_string(),
            "^bugfix.*$".to_string(),
        ],
        order: vec![
            "^(master|main|trunk)$".to_string(),
            "^(hotfix|release).*$".to_string(),
            "^(develop|dev)$".to_string(),
        ],
        terminal_matches: vec![
            ("^(master|main|trunk)$".to_string(), vec!["bright_blue".to_string()]),
            ("^(develop|dev)$".to_string(), vec!["bright_yellow".to_string()]),
            ("^(feature|fork/).*$".to_string(), vec!["bright_magenta".to_string(), "bright_cyan".to_string()]),
            ("^release.*$".to_string(), vec!["bright_green".to_string()]),
            ("^(bugfix|hotfix).*$".to_string(), vec!["bright_red".to_string()]),
            ("^tags/.*$".to_string(), vec!["bright_green".to_string()]),
        ],
        terminal_unknown: vec!["white".to_string()],
        svg_matches: vec![
            ("^(master|main|trunk)$".to_string(), vec!["blue".to_string()]),
            ("^(develop|dev)$".to_string(), vec!["gold".to_string()]),
            ("^(feature|fork/).*$".to_string(), vec!["magenta".to_string(), "darkcyan".to_string()]),
            ("^release.*$".to_string(), vec!["green".to_string()]),
            ("^(bugfix|hotfix).*$".to_string(), vec!["red".to_string()]),
            ("^tags/.*$".to_string(), vec!["green".to_string()]),
        ],
        svg_unknown: vec!["gray".to_string()],
    }
}

fn get_builtin_simple() -> ModelConfig {
    ModelConfig {
        name: "simple".to_string(),
        persistence: vec!["^(master|main|trunk)$".to_string()],
        order: vec!["^(master|main|trunk)$".to_string()],
        terminal_matches: vec![
            ("^(master|main|trunk)$".to_string(), vec!["bright_blue".to_string()]),
        ],
        terminal_unknown: vec![
            "bright_red".to_string(), "bright_green".to_string(), "bright_yellow".to_string(),
            "bright_blue".to_string(), "bright_magenta".to_string(), "bright_cyan".to_string(),
        ],
        svg_matches: vec![
            ("^(master|main|trunk)$".to_string(), vec!["blue".to_string()]),
        ],
        svg_unknown: vec![
            "red".to_string(), "green".to_string(), "yellow".to_string(),
            "blue".to_string(), "magenta".to_string(), "cyan".to_string(),
        ],
    }
}

fn get_builtin_none() -> ModelConfig {
    ModelConfig {
        name: "none".to_string(),
