use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_uint};

#[repr(C)] pub struct git_repository { _unused: [u8; 0] }
#[repr(C)] pub struct git_reference { _unused: [u8; 0] }
#[repr(C)] pub struct git_reference_iterator { _unused: [u8; 0] }
#[repr(C)] pub struct git_revwalk { _unused: [u8; 0] }
#[repr(C)] pub struct git_commit { _unused: [u8; 0] }
#[repr(C)] pub struct git_object { _unused: [u8; 0] }

#[repr(C)]
#[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
pub struct git_oid {
    pub id: [u8; 20],
}

impl git_oid {
    pub fn to_hex(&self) -> String {
        let mut s = String::with_capacity(40);
        for b in &self.id {
            s.push_str(&format!("{:02x}", b));
        }
        s
    }
}

#[repr(C)]
pub struct git_time {
    pub time: i64,
    pub offset: c_int,
    pub sign: c_char,
}

#[repr(C)]
pub struct git_signature {
    pub name: *const c_char,
    pub email: *const c_char,
    pub when: git_time,
}

#[repr(C)]
pub struct git_error {
    pub message: *const c_char,
    pub klass: c_int,
}

const GIT_OPT_SET_OWNER_VALIDATION: c_int = 28;
const GIT_OBJECT_COMMIT: c_int = 1;
const GIT_SORT_TOPOLOGICAL: c_uint = 1;
const GIT_SORT_TIME: c_uint = 2;

extern "C" {
    fn git_libgit2_init() -> c_int;
    fn git_libgit2_shutdown() -> c_int;
    fn git_libgit2_opts(opt: c_int, ...) -> c_int;
    fn git_error_last() -> *const git_error;

    fn git_repository_open_ext(out: *mut *mut git_repository, path: *const c_char, flags: c_uint, ceiling_dirs: *const c_char) -> c_int;
    fn git_repository_free(repo: *mut git_repository);
    fn git_repository_head(out: *mut *mut git_reference, repo: *mut git_repository) -> c_int;

    fn git_reference_iterator_new(out: *mut *mut git_reference_iterator, repo: *mut git_repository) -> c_int;
    fn git_reference_next(out: *mut *mut git_reference, iter: *mut git_reference_iterator) -> c_int;
    fn git_reference_iterator_free(iter: *mut git_reference_iterator);
    fn git_reference_name(ref_: *const git_reference) -> *const c_char;
    fn git_reference_target(ref_: *const git_reference) -> *const git_oid;
    fn git_reference_symbolic_target(ref_: *const git_reference) -> *const c_char;
    fn git_reference_type(ref_: *const git_reference) -> c_int;
    fn git_reference_is_branch(ref_: *const git_reference) -> c_int;
    fn git_reference_is_tag(ref_: *const git_reference) -> c_int;
    fn git_reference_is_remote(ref_: *const git_reference) -> c_int;
    fn git_reference_peel(out: *mut *mut git_object, ref_: *const git_reference, type_: c_int) -> c_int;
    fn git_reference_free(ref_: *mut git_reference);

    fn git_object_free(obj: *mut git_object);
    fn git_object_id(obj: *const git_object) -> *const git_oid;

    fn git_revwalk_new(out: *mut *mut git_revwalk, repo: *mut git_repository) -> c_int;
    fn git_revwalk_sorting(walk: *mut git_revwalk, sort_mode: c_uint) -> c_int;
    fn git_revwalk_push_glob(walk: *mut git_revwalk, glob: *const c_char) -> c_int;
    fn git_revwalk_push_head(walk: *mut git_revwalk) -> c_int;
    fn git_revwalk_next(out: *mut git_oid, walk: *mut git_revwalk) -> c_int;
    fn git_revwalk_free(walk: *mut git_revwalk);

    fn git_commit_lookup(out: *mut *mut git_commit, repo: *mut git_repository, id: *const git_oid) -> c_int;
    fn git_commit_free(commit: *mut git_commit);
    fn git_commit_summary(commit: *const git_commit) -> *const c_char;
    fn git_commit_body(commit: *const git_commit) -> *const c_char;
    fn git_commit_raw_header(commit: *const git_commit) -> *const c_char;
    fn git_commit_author(commit: *const git_commit) -> *const git_signature;
    fn git_commit_committer(commit: *const git_commit) -> *const git_signature;
    fn git_commit_parentcount(commit: *const git_commit) -> c_uint;
    fn git_commit_parent(out: *mut *mut git_commit, commit: *const git_commit, n: c_uint) -> c_int;
    fn git_commit_id(commit: *const git_commit) -> *const git_oid;
}

#[derive(Debug, Clone)]
pub struct GitRef {
    pub name: String,         // full ref name e.g. refs/heads/master
    pub display_name: String, // e.g. master, tags/v1.0
    pub target_oid: String,   // hex OID
    pub is_head: bool,
    pub is_branch: bool,
    pub is_tag: bool,
    pub is_remote: bool,
}

#[derive(Debug, Clone)]
pub struct GitCommit {
    pub oid: String,
    pub short_oid: String,
    pub parents: Vec<String>,
    pub short_parents: Vec<String>,
    pub summary: String,
    pub body: String,
    pub author_name: String,
    pub author_email: String,
    pub author_time: i64,
    pub author_offset: i32,
    pub committer_name: String,
    pub committer_email: String,
    pub committer_time: i64,
    pub committer_offset: i32,
}

pub struct GitRepo {
    raw_repo: *mut git_repository,
}

impl GitRepo {
    pub fn open(path_str: &str, skip_owner_validation: bool) -> Result<GitRepo, String> {
        unsafe {
            git_libgit2_init();
            if skip_owner_validation {
                git_libgit2_opts(GIT_OPT_SET_OWNER_VALIDATION, 0);
            }
            let c_path = CString::new(path_str).map_err(|e| e.to_string())?;
            let mut raw_repo: *mut git_repository = std::ptr::null_mut();
            let res = git_repository_open_ext(&mut raw_repo, c_path.as_ptr(), 0, std::ptr::null());
            if res != 0 {
                return Err(format!(
                    "ERROR: could not find repository at '{}'\n       Navigate into a repository before running git-graph, or use option --path",
                    path_str
                ));
            }
            Ok(GitRepo { raw_repo })
        }
    }

    pub fn get_head_branch_name(&self) -> Option<String> {
        unsafe {
            let mut head_ref: *mut git_reference = std::ptr::null_mut();
            if git_repository_head(&mut head_ref, self.raw_repo) == 0 {
                if git_reference_is_branch(head_ref) != 0 {
                    let name_ptr = git_reference_name(head_ref);
                    if !name_ptr.is_null() {
                        let full_name = CStr::from_ptr(name_ptr).to_string_lossy().to_string();
                        git_reference_free(head_ref);
                        if let Some(stripped) = full_name.strip_prefix("refs/heads/") {
                            return Some(stripped.to_string());
                        }
                    }
                }
                git_reference_free(head_ref);
            }
        }
        None
    }

    pub fn get_refs(&self, local_only: bool) -> Vec<GitRef> {
        let mut refs = Vec::new();
        let head_branch = self.get_head_branch_name();

        unsafe {
            let mut head_ref: *mut git_reference = std::ptr::null_mut();
            let mut head_target_oid: Option<String> = None;
            if git_repository_head(&mut head_ref, self.raw_repo) == 0 {
                let mut peeled: *mut git_object = std::ptr::null_mut();
                if git_reference_peel(&mut peeled, head_ref, GIT_OBJECT_COMMIT) == 0 {
                    let oid_ptr = git_object_id(peeled);
                    if !oid_ptr.is_null() {
                        head_target_oid = Some((*oid_ptr).to_hex());
                    }
                    git_object_free(peeled);
                }
                git_reference_free(head_ref);
            }

            let mut iter: *mut git_reference_iterator = std::ptr::null_mut();
            if git_reference_iterator_new(&mut iter, self.raw_repo) == 0 {
                let mut ref_: *mut git_reference = std::ptr::null_mut();
                while git_reference_next(&mut ref_, iter) == 0 {
                    let name_ptr = git_reference_name(ref_);
                    if !name_ptr.is_null() {
                        let full_name = CStr::from_ptr(name_ptr).to_string_lossy().to_string();
                        let is_b = git_reference_is_branch(ref_) != 0;
                        let is_t = git_reference_is_tag(ref_) != 0;
                        let is_r = git_reference_is_remote(ref_) != 0;

                        if local_only && is_r {
                            git_reference_free(ref_);
                            continue;
                        }

                        let mut target_oid = String::new();
                        let mut peeled: *mut git_object = std::ptr::null_mut();
                        if git_reference_peel(&mut peeled, ref_, GIT_OBJECT_COMMIT) == 0 {
                            let oid_ptr = git_object_id(peeled);
                            if !oid_ptr.is_null() {
                                target_oid = (*oid_ptr).to_hex();
                            }
                            git_object_free(peeled);
                        }

                        if !target_oid.is_empty() {
                            let display_name = if let Some(stripped) = full_name.strip_prefix("refs/heads/") {
                                stripped.to_string()
                            } else if let Some(stripped) = full_name.strip_prefix("refs/remotes/") {
                                stripped.to_string()
                            } else if let Some(stripped) = full_name.strip_prefix("refs/tags/") {
                                format!("tags/{}", stripped)
                            } else {
                                full_name.clone()
                            };

                            let is_head = head_branch.as_ref() == Some(&display_name);

                            refs.push(GitRef {
                                name: full_name,
                                display_name,
                                target_oid,
                                is_head,
                                is_branch: is_b,
                                is_tag: is_t,
                                is_remote: is_r,
                            });
                        }
                    }
                    git_reference_free(ref_);
                }
                git_reference_iterator_free(iter);
            }
        }

        refs
