            git_libgit2_init();
            if skip_owner_validation {
                git_libgit2_opts(GIT_OPT_SET_OWNER_VALIDATION, 0);
            }
            let c_path = CString::new(path_str).map_err(|e| e.to_string())?;
            let mut raw_repo: *mut git_repository = std::ptr::null_mut();
            let res = git_repository_open_ext(&mut raw_repo, c_path.as_ptr(), 0, std::ptr::null());
            if res != 0 {
                return Err(format!(
                    "ERROR: could not find repository at '{}'\n       Navigate into a repository before running git-graph, or use option --path",
