        unsafe {
            let mut head_ref: *mut git_reference = std::ptr::null_mut();
            if git_repository_head(&mut head_ref, self.raw_repo) == 0 {
                if git_reference_is_branch(head_ref) != 0 {
                    let name_ptr = git_reference_name(head_ref);
                    if !name_ptr.is_null() {
                        let full_name = CStr::from_ptr(name_ptr).to_string_lossy().to_string();
                        git_reference_free(head_ref);
                        if let Some(stripped) = full_name.strip_prefix("refs/heads/") {
                            return Some(stripped.to_string());
                        }
                    }
                }
                git_reference_free(head_ref);
            }
        }
        None
    }

