                let mut peeled: *mut git_object = std::ptr::null_mut();
                if git_reference_peel(&mut peeled, head_ref, GIT_OBJECT_COMMIT) == 0 {
                    let oid_ptr = git_object_id(peeled);
                    if !oid_ptr.is_null() {
                        head_target_oid = Some((*oid_ptr).to_hex());
