                            git_reference_free(ref_);
                            continue;
                        }

                        let mut target_oid = String::new();
                        let mut peeled: *mut git_object = std::ptr::null_mut();
                        if git_reference_peel(&mut peeled, ref_, GIT_OBJECT_COMMIT) == 0 {
                            let oid_ptr = git_object_id(peeled);
                            if !oid_ptr.is_null() {
                                target_oid = (*oid_ptr).to_hex();
                            }
                            git_object_free(peeled);
                        }

                        if !target_oid.is_empty() {
                            let display_name = if let Some(stripped) = full_name.strip_prefix("refs/heads/") {
                                stripped.to_string()
                            } else if let Some(stripped) = full_name.strip_prefix("refs/remotes/") {
                                stripped.to_string()
                            } else if let Some(stripped) = full_name.strip_prefix("refs/tags/") {
                                format!("tags/{}", stripped)
                            } else {
                                full_name.clone()
                            };

