                            if !p_oid_ptr.is_null() {
                                let p_hex = (*p_oid_ptr).to_hex();
                                short_parents.push(p_hex[..7].to_string());
                                parents.push(p_hex);
                            }
                            git_commit_free(parent_commit);
                        }
                    }

                    let summary_ptr = git_commit_summary(raw_commit);
                    let summary = if !summary_ptr.is_null() {
                        CStr::from_ptr(summary_ptr).to_string_lossy().to_string()
                    } else {
