    pub fn open(path_str: &str, skip_owner_validation: bool) -> Result<GitRepo, String> {
        unsafe {
            git_libgit2_init();
            if skip_owner_validation {
                git_libgit2_opts(GIT_OPT_SET_OWNER_VALIDATION, 0);
            }
            let c_path = CString::new(path_str).map_err(|e| e.to_string())?;
            let mut raw_repo: *mut git_repository = std::ptr::null_mut();
            let res = git_repository_open_ext(&mut raw_repo, c_path.as_ptr(), 0, std::ptr::null());
            if res != 0 {
                return Err(format!(
                    "ERROR: could not find repository at '{}'\n       Navigate into a repository before running git-graph, or use option --path",
                    path_str
                ));
            }
            Ok(GitRepo { raw_repo })
        }
    }

    pub fn get_head_branch_name(&self) -> Option<String> {
        unsafe {
            let mut head_ref: *mut git_reference = std::ptr::null_mut();
            if git_repository_head(&mut head_ref, self.raw_repo) == 0 {
                if git_reference_is_branch(head_ref) != 0 {
                    let name_ptr = git_reference_name(head_ref);
                    if !name_ptr.is_null() {
                        let full_name = CStr::from_ptr(name_ptr).to_string_lossy().to_string();
                        git_reference_free(head_ref);
                        if let Some(stripped) = full_name.strip_prefix("refs/heads/") {
                            return Some(stripped.to_string());
                        }
                    }
                }
                git_reference_free(head_ref);
            }
        }
        None
    }

    pub fn get_refs(&self, local_only: bool) -> Vec<GitRef> {
        let mut refs = Vec::new();
        let head_branch = self.get_head_branch_name();

        unsafe {
            let mut head_ref: *mut git_reference = std::ptr::null_mut();
            let mut head_target_oid: Option<String> = None;
            if git_repository_head(&mut head_ref, self.raw_repo) == 0 {
                let mut peeled: *mut git_object = std::ptr::null_mut();
                if git_reference_peel(&mut peeled, head_ref, GIT_OBJECT_COMMIT) == 0 {
                    let oid_ptr = git_object_id(peeled);
                    if !oid_ptr.is_null() {
                        head_target_oid = Some((*oid_ptr).to_hex());
                    }
                    git_object_free(peeled);
                }
                git_reference_free(head_ref);
            }

            let mut iter: *mut git_reference_iterator = std::ptr::null_mut();
            if git_reference_iterator_new(&mut iter, self.raw_repo) == 0 {
                let mut ref_: *mut git_reference = std::ptr::null_mut();
                while git_reference_next(&mut ref_, iter) == 0 {
                    let name_ptr = git_reference_name(ref_);
                    if !name_ptr.is_null() {
                        let full_name = CStr::from_ptr(name_ptr).to_string_lossy().to_string();
                        let is_b = git_reference_is_branch(ref_) != 0;
                        let is_t = git_reference_is_tag(ref_) != 0;
                        let is_r = git_reference_is_remote(ref_) != 0;

                        if local_only && is_r {
                            git_reference_free(ref_);
                            continue;
                        }

                        let mut target_oid = String::new();
                        let mut peeled: *mut git_object = std::ptr::null_mut();
                        if git_reference_peel(&mut peeled, ref_, GIT_OBJECT_COMMIT) == 0 {
                            let oid_ptr = git_object_id(peeled);
                            if !oid_ptr.is_null() {
                                target_oid = (*oid_ptr).to_hex();
                            }
                            git_object_free(peeled);
                        }

                        if !target_oid.is_empty() {
                            let display_name = if let Some(stripped) = full_name.strip_prefix("refs/heads/") {
                                stripped.to_string()
                            } else if let Some(stripped) = full_name.strip_prefix("refs/remotes/") {
                                stripped.to_string()
                            } else if let Some(stripped) = full_name.strip_prefix("refs/tags/") {
                                format!("tags/{}", stripped)
                            } else {
                                full_name.clone()
                            };

                            let is_head = head_branch.as_ref() == Some(&display_name);

                            refs.push(GitRef {
                                name: full_name,
                                display_name,
                                target_oid,
                                is_head,
                                is_branch: is_b,
                                is_tag: is_t,
                                is_remote: is_r,
                            });
                        }
                    }
                    git_reference_free(ref_);
                }
                git_reference_iterator_free(iter);
            }
        }

        refs
    }

    pub fn walk_commits(&self) -> Result<Vec<GitCommit>, String> {
        let mut commits = Vec::new();
        unsafe {
            let mut walk: *mut git_revwalk = std::ptr::null_mut();
            if git_revwalk_new(&mut walk, self.raw_repo) != 0 {
                return Err("Failed to create revwalk".to_string());
            }

            git_revwalk_sorting(walk, GIT_SORT_TOPOLOGICAL | GIT_SORT_TIME);

            let glob = CString::new("refs/*").unwrap();
            git_revwalk_push_glob(walk, glob.as_ptr());
            git_revwalk_push_head(walk);

            let mut oid = git_oid { id: [0; 20] };
            while git_revwalk_next(&mut oid, walk) == 0 {
                let mut raw_commit: *mut git_commit = std::ptr::null_mut();
                if git_commit_lookup(&mut raw_commit, self.raw_repo, &oid) == 0 {
                    let hex_oid = oid.to_hex();
                    let short_oid = hex_oid[..7].to_string();

                    let parent_count = git_commit_parentcount(raw_commit);
                    let mut parents = Vec::new();
                    let mut short_parents = Vec::new();
                    for i in 0..parent_count {
                        let mut parent_commit: *mut git_commit = std::ptr::null_mut();
                        if git_commit_parent(&mut parent_commit, raw_commit, i) == 0 {
                            let p_oid_ptr = git_commit_id(parent_commit);
                            if !p_oid_ptr.is_null() {
                                let p_hex = (*p_oid_ptr).to_hex();
                                short_parents.push(p_hex[..7].to_string());
                                parents.push(p_hex);
                            }
                            git_commit_free(parent_commit);
                        }
                    }

                    let summary_ptr = git_commit_summary(raw_commit);
                    let summary = if !summary_ptr.is_null() {
                        CStr::from_ptr(summary_ptr).to_string_lossy().to_string()
                    } else {
                        String::new()
                    };

                    let body_ptr = git_commit_body(raw_commit);
                    let body = if !body_ptr.is_null() {
                        CStr::from_ptr(body_ptr).to_string_lossy().to_string()
                    } else {
                        String::new()
                    };

                    let author_ptr = git_commit_author(raw_commit);
                    let (author_name, author_email, author_time, author_offset) = if !author_ptr.is_null() {
                        let name = if !(*author_ptr).name.is_null() {
                            CStr::from_ptr((*author_ptr).name).to_string_lossy().to_string()
                        } else { String::new() };
                        let email = if !(*author_ptr).email.is_null() {
                            CStr::from_ptr((*author_ptr).email).to_string_lossy().to_string()
                        } else { String::new() };
                        (name, email, (*author_ptr).when.time, (*author_ptr).when.offset)
                    } else {
                        (String::new(), String::new(), 0, 0)
                    };

                    let committer_ptr = git_commit_committer(raw_commit);
                    let (committer_name, committer_email, committer_time, committer_offset) = if !committer_ptr.is_null() {
                        let name = if !(*committer_ptr).name.is_null() {
                            CStr::from_ptr((*committer_ptr).name).to_string_lossy().to_string()
                        } else { String::new() };
                        let email = if !(*committer_ptr).email.is_null() {
                            CStr::from_ptr((*committer_ptr).email).to_string_lossy().to_string()
                        } else { String::new() };
                        (name, email, (*committer_ptr).when.time, (*committer_ptr).when.offset)
                    } else {
                        (String::new(), String::new(), 0, 0)
                    };

                    commits.push(GitCommit {
                        oid: hex_oid,
                        short_oid,
                        parents,
                        short_parents,
                        summary,
                        body,
                        author_name,
                        author_email,
                        author_time,
                        author_offset,
                        committer_name,
                        committer_email,
                        committer_time,
                        committer_offset,
                    });

                    git_commit_free(raw_commit);
                }
            }

            git_revwalk_free(walk);
        }

        if commits.is_empty() {
            return Err("reference 'refs/heads/master' not found".to_string());
        }

        Ok(commits)
    }
}

impl Drop for GitRepo {
    fn drop(&mut self) {
        unsafe {
            if !self.raw_repo.is_null() {
                git_repository_free(self.raw_repo);
            }
            git_libgit2_shutdown();
        }
    }
}
