            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("toml") {
                    if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                        result.push(stem.to_string());
                    }
                }
            }
        }
        result
    } else {
        vec!["git-flow".to_string(), "simple".to_string(), "none".to_string()]
    }
}

pub fn load_model(name: &str) -> Result<ModelConfig, String> {
    if let Some(models_dir) = get_models_dir() {
        let toml_path = models_dir.join(format!("{}.toml", name));
        if toml_path.exists() {
            if let Ok(content) = fs::read_to_string(&toml_path) {
                if let Ok(config) = parse_toml_model(name, &content) {
                    return Ok(config);
                }
            }
        }
        let available = list_models().join(", ");
        let dir_str = models_dir.to_string_lossy();
        return Err(format!(
            "ERROR: No branching model named '{}' found in {}\n       Available models are: {}",
            name, dir_str, available
        ));
    }

    match name {
        "git-flow" => Ok(get_builtin_git_flow()),
        "simple" => Ok(get_builtin_simple()),
        "none" => Ok(get_builtin_none()),
        _ => {
            let config_dir_str = get_config_dir()
                .map(|p| p.join("git-graph").join("models").to_string_lossy().to_string())
                .unwrap_or_else(|| "/home/agent/.config/git-graph/models".to_string());
            Err(format!(
                "ERROR: No branching model named '{}' found in {}\n       Available models are: git-flow, simple, none",
                name, config_dir_str
            ))
        }
    }
}

