{"command":"cat <<'EOF' > src/graph.rs
use std::collections::{HashMap, HashSet};
use crate::git::{GitCommit, GitRef};
use crate::model::ModelConfig;

#[derive(Debug, Clone)]
pub struct TrackedBranch {
    pub name: String,
    pub column: usize,
    pub start_commit_idx: Option<usize>,
    pub end_commit_idx: Option<usize>,
    pub source_order_group: usize,
    pub target_order_group: usize,
    pub term_color: String,
    pub svg_color: String,
}

#[derive(Debug, Clone)]
pub struct CommitNode {
    pub commit: GitCommit,
    pub branch_idx: usize,
    pub column: usize,
    pub ref_text: String,
    pub refs: Vec<GitRef>,
}

pub struct GraphData {
    pub nodes: Vec<CommitNode>,
    pub branches: Vec<TrackedBranch>,
}

fn simple_regex_match(pattern: &str, text: &str) -> bool {
    // Basic regex matching for branch model patterns
    if pattern == ".*" || pattern == "^.*$" {
        return true;
    }
    // Handle exact or prefix matches
    let clean_pat = pattern.trim_start_matches('^').trim_end_matches('$');
    if clean_pat.starts_with('(') && clean_pat.ends_with(')') {
        let options = &clean_pat[1..clean_pat.len() - 1];
        for opt in options.split('|') {
            if text == opt {
                return true;
            }
        }
    }
    if clean_pat.contains(".*") {
        let prefix = clean_pat.split(".*").next().unwrap_or("");
        if text.starts_with(prefix) {
            return true;
        }
    }
    if text == clean_pat {
        return true;
    }
    false
}

pub fn build_graph(
    commits: &[GitCommit],
    refs: &[GitRef],
    model: &ModelConfig,
    model_override: Option<&str>,
) -> GraphData {
    let mut commit_map: HashMap<String, usize> = HashMap::new();
    for (idx, c) in commits.iter().enumerate() {
        commit_map.insert(c.oid.clone(), idx);
    }

    // 1. Calculate persistence rank for candidate refs
    struct RefCandidate {
        git_ref: GitRef,
        persistence: usize,
        commit_idx: usize,
    }

    let mut candidates = Vec::new();
    for r in refs {
        if let Some(&c_idx) = commit_map.get(&r.target_oid) {
            let mut persistence = 9999;
            for (p_idx, pat) in model.persistence.iter().enumerate() {
                if simple_regex_match(pat, &r.display_name) {
                    persistence = p_idx;
                    break;
                }
            }
            candidates.push(RefCandidate {
                git_ref: r.clone(),
                persistence,
                commit_idx: c_idx,
            });
        }
    }

    // Sort candidates by persistence, then commit_idx, then display_name
    candidates.sort_by(|a, b| {
        a.persistence
            .cmp(&b.persistence)
            .then(a.commit_idx.cmp(&b.commit_idx))
            .then(a.git_ref.display_name.cmp(&b.git_ref.display_name))
    });

    // 2. Trace branches to commits
    let mut commit_to_branch: HashMap<String, usize> = HashMap::new();
    let mut branches: Vec<TrackedBranch> = Vec::new();

    for cand in candidates {
        let start_oid = cand.git_ref.target_oid.clone();
        if commit_to_branch.contains_key(&start_oid) {
            // Already claimed by higher-persistence branch
            continue;
        }

        let branch_idx = branches.len();
        let mut curr_oid = Some(start_oid);
        let mut start_commit_idx = None;
        let mut end_commit_idx = None;

        while let Some(oid) = curr_oid {
            if commit_to_branch.contains_key(&oid) {
                break;
            }
            if let Some(&c_idx) = commit_map.get(&oid) {
                commit_to_branch.insert(oid.clone(), branch_idx);
                if start_commit_idx.is_none() || c_idx < start_commit_idx.unwrap() {
                    start_commit_idx = Some(c_idx);
                }
                if end_commit_idx.is_none() || c_idx > end_commit_idx.unwrap() {
                    end_commit_idx = Some(c_idx);
                }

                let commit = &commits[c_idx];
                if !commit.parents.is_empty() {
                    curr_oid = Some(commit.parents[0].clone());
                } else {
                    curr_oid = None;
                }
            } else {
                curr_oid = None;
            }
        }

        // Calculate order group
        let mut order_group = 9999;
        for (o_idx, pat) in model.order.iter().enumerate() {
            if simple_regex_match(pat, &cand.git_ref.display_name) {
                order_group = o_idx;
                break;
            }
        }

        // Determine colors
        let mut term_color = "white".to_string();
        for (pat, colors) in &model.terminal_matches {
            if simple_regex_match(pat, &cand.git_ref.display_name) {
                if !colors.is_empty() {
                    term_color = colors[0].clone();
                }
                break;
            }
        }
        if term_color == "white" && !model.terminal_unknown.is_empty() {
            let color_idx = branch_idx % model.terminal_unknown.len();
            term_color = model.terminal_unknown[color_idx].clone();
        }

        let mut svg_color = "gray".to_string();
        for (pat, colors) in &model.svg_matches {
            if simple_regex_match(pat, &cand.git_ref.display_name) {
                if !colors.is_empty() {
                    svg_color = colors[0].clone();
                }
                break;
            }
        }
        if svg_color == "gray" && !model.svg_unknown.is_empty() {
            let color_idx = branch_idx % model.svg_unknown.len();
            svg_color = model.svg_unknown[color_idx].clone();
        }

        branches.push(TrackedBranch {
            name: cand.git_ref.display_name,
            column: 0,
            start_commit_idx,
            end_commit_idx,
            source_order_group: order_group,
            target_order_group: order_group,
            term_color,
            svg_color,
        });
    }

    // 3. Filter commits that have assigned branches
    let mut filtered_commits = Vec::new();
    for c in commits {
        if commit_to_branch.contains_key(&c.oid) {
            filtered_commits.push(c.clone());
        }
    }

    // Map filtered indices
    let mut filtered_commit_map = HashMap::new();
    for (f_idx, c) in filtered_commits.iter().enumerate() {
        filtered_commit_map.insert(c.oid.clone(), f_idx);
    }

    // Update branch start/end indices to filtered commit indices
    for b in &mut branches {
        let mut min_idx = None;
        let mut max_idx = None;
        for (oid, &b_idx) in &commit_to_branch {
            if branches.len() > b_idx && branches[b_idx].name == b.name {
                if let Some(&f_idx) = filtered_commit_map.get(oid) {
                    if min_idx.is_none() || f_idx < min_idx.unwrap() {
                        min_idx = Some(f_idx);
                    }
                    if max_idx.is_none() || f_idx > max_idx.unwrap() {
                        max_idx = Some(f_idx);
                    }
                }
            }
        }
        b.start_commit_idx = min_idx;
        b.end_commit_idx = max_idx;
    }

    // 4. Assign columns to branches
    // Group branches by order_group, allocate columns
    let mut columns: Vec<Vec<(usize, usize)>> = Vec::new(); // occupied ranges (start, end)
    for b in &mut branches {
        if let (Some(start), Some(end)) = (b.start_commit_idx, b.end_commit_idx) {
            let mut assigned_col = None;
            for (col_idx, occupied) in columns.iter_mut().enumerate() {
                let mut overlap = false;
                for &(o_start, o_end) in occupied.iter() {
                    if !(end < o_start || start > o_end) {
                        overlap = true;
                        break;
                    }
                }
                if !overlap {
                    occupied.push((start, end));
                    assigned_col = Some(col_idx);
                    break;
                }
            }
            if assigned_col.is_none() {
                let col_idx = columns.len();
                columns.push(vec![(start, end)]);
                assigned_col = Some(col_idx);
            }
            b.column = assigned_col.unwrap();
        } else {
            b.column = 99; // unassigned
        }
    }

    // 5. Construct nodes
    let mut nodes = Vec::new();
    for c in &filtered_commits {
        let b_idx = commit_to_branch.get(&c.oid).copied().unwrap_or(0);
        let col = if branches.len() > b_idx {
            branches[b_idx].column
        } else {
            0
        };

        // Find refs matching this commit
        let mut matching_refs: Vec<GitRef> = refs
            .iter()
            .filter(|r| r.target_oid == c.oid)
            .cloned()
            .collect();

        // Format ref_text
        let mut ref_parts = Vec::new();
        let mut tag_parts = Vec::new();

        // Check if HEAD is here
        let head_ref = matching_refs.iter().find(|r| r.is_head);
        if let Some(h) = head_ref {
            ref_parts.push(format!("HEAD -> {}", h.display_name));
        }

        for r in &matching_refs {
            if r.is_head {
                continue;
            }
            if r.is_tag {
                let tag_name = r.display_name.strip_prefix("tags/").unwrap_or(&r.display_name);
                tag_parts.push(tag_name.to_string());
            } else {
                ref_parts.push(r.display_name.clone());
            }
        }

        let mut ref_text = String::new();
        if !ref_parts.is_empty() {
            ref_text.push_str(&format!("({})", ref_parts.join(", ")));
        }
        if !tag_parts.is_empty() {
            if !ref_text.is_empty() {
                ref_text.push(' ');
            }
            ref_text.push_str(&format!("[{}]", tag_parts.join(", ")));
        }

        nodes.push(CommitNode {
            commit: c.clone(),
            branch_idx: b_idx,
            column: col,
            ref_text,
            refs: matching_refs,
        });
    }

    GraphData { nodes, branches }
}
EOF"}

