pub fn format_git_date(timestamp: i64, offset_minutes: i32) -> String {
    // Format: Fri Jul 31 06:01:19 2026 +0000
    let days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

    // Adjust for offset
    let local_ts = timestamp + (offset_minutes as i64 * 60);

    // Unix epoch day calculation
    let secs_per_day = 86400;
    let day_num = (local_ts / secs_per_day) + 719468; // days from 0001-01-01
    let day_of_week = ((local_ts / secs_per_day + 4) % 7 + 7) % 7; // 0 = Sun

    let era = day_num / 146097;
    let doe = day_num - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };

    let secs_in_day = ((local_ts % secs_per_day) + secs_per_day) % secs_per_day;
    let hours = secs_in_day / 3600;
    let mins = (secs_in_day % 3600) / 60;
    let secs = secs_in_day % 60;

    let sign = if offset_minutes >= 0 { '+' } else { '-' };
    let abs_off = offset_minutes.abs();
    let off_h = abs_off / 60;
    let off_m = abs_off % 60;

    format!(
        "{} {} {:2} {:02}:{:02}:{:02} {} {}{:02}{:02}",
        days[day_of_week as usize],
        months[(m - 1) as usize],
        d,
        hours,
        mins,
        secs,
        year,
        sign,
        off_h,
        off_m
    )
}

pub fn format_git_date_short(timestamp: i64, offset_minutes: i32) -> String {
    let local_ts = timestamp + (offset_minutes as i64 * 60);
    let day_num = (local_ts / 86400) + 719468;
    let era = day_num / 146097;
    let doe = day_num - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };

    format!("{:04}-{:02}-{:02}", year, m, d)
}

pub fn format_git_date_relative(timestamp: i64) -> String {
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(timestamp);

    let diff = if now >= timestamp { now - timestamp } else { 0 };

    if diff < 60 {
        format!("{} seconds ago", diff)
    } else if diff < 120 {
        "1 minute ago".to_string()
    } else if diff < 3600 {
        format!("{} minutes ago", diff / 60)
    } else if diff < 7200 {
        "1 hour ago".to_string()
    } else if diff < 86400 {
        format!("{} hours ago", diff / 3600)
    } else if diff < 172800 {
        "1 day ago".to_string()
    } else if diff < 604800 {
        format!("{} days ago", diff / 86400)
    } else if diff < 1209600 {
        "1 week ago".to_string()
    } else if diff < 2592000 {
        format!("{} weeks ago", diff / 604800)
    } else if diff < 5184000 {
        "1 month ago".to_string()
    } else if diff < 31536000 {
        format!("{} months ago", diff / 2592000)
    } else if diff < 63072000 {
        "1 year ago".to_string()
    } else {
        format!("{} years ago", diff / 31536000)
    }
}

pub fn render_text(
    graph: &GraphData,
    args: &CliArgs,
    use_color: bool,
) {
    let charset = get_charset(&args.style);

    // Calculate max columns
    let mut max_col = 0;
    for b in &graph.branches {
        if b.column < 99 && b.column > max_col {
            max_col = b.column;
        }
    }

    let mut nodes = graph.nodes.clone();
    if args.reverse {
        nodes.reverse();
    }

    if let Some(max_c) = args.max_count {
        if nodes.len() > max_c {
            nodes.truncate(max_c);
        }
    }

    // Determine format string
    let fmt_str = match args.format.as_str() {
        "oneline" | "o" => "%h%d %s",
        "short" | "s" => "commit %H%d%nAuthor: %an <%ae>%n%n    %s%n",
        "medium" | "m" => "commit %H%d%nAuthor: %an <%ae>%nDate:   %ad%n%n    %s%+b%n",
        "full" | "f" => "commit %H%d%nAuthor: %an <%ae>%nCommit: %cn <%ce>%nDate:   %cd%n%n    %s%+b%n",
        other => autre_format(other),
    };

    // Render nodes
    for (i, node) in nodes.iter().enumerate() {
        let col = node.column;
        let is_merge = node.commit.parents.len() > 1;
        let dot_char = if is_merge { charset.merge_dot } else { charset.commit_dot };

        // Build graph line prefix
        let mut graph_prefix = String::new();
        for c in 0..=max_col {
            if c == col {
                graph_prefix.push_str(dot_char);
                graph_prefix.push_str("  ");
            } else {
                graph_prefix.push_str("   ");
            }
        }

        // Format commit text
        let formatted_text = format_commit_text(node, fmt_str, use_color, graph);

        println!("{}{}", graph_prefix, formatted_text);
    }
}

fn autre_format(input: &str) -> &str {
    if input.starts_with('s') {
        "commit %H%d%nAuthor: %an <%ae>%n%n    %s%n"
    } else if input.starts_with('m') {
        "commit %H%d%nAuthor: %an <%ae>%nDate:   %ad%n%n    %s%+b%n"
    } else if input.starts_with('f') {
        "commit %H%d%nAuthor: %an <%ae>%nCommit: %cn <%ce>%nDate:   %cd%n%n    %s%+b%n"
    } else if input.starts_with('o') {
        "%h%d %s"
    } else {
        input
    }
}

fn format_commit_text(
    node: &CommitNode,
    fmt: &str,
    use_color: bool,
    graph: &GraphData,
) -> String {
    let c = &node.commit;
    let mut result = String::new();
    let mut chars = fmt.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '%' {
            let mut modifier = None;
            if let Some(&next_c) = chars.peek() {
                if next_c == '+' || next_c == '-' || next_c == ' ' {
                    modifier = Some(next_c);
                    chars.next();
                }
            }

            let mut ph = String::new();
            while let Some(&next_c) = chars.peek() {
                if next_c.is_alphabetic() {
                    ph.push(next_c);
                    chars.next();
                    if ph == "an" || ph == "ae" || ph == "ad" || ph == "as" || ph == "ar"
                        || ph == "cn" || ph == "ce" || ph == "cd" || ph == "cs" || ph == "cr" {
                        break;
                    }
                } else {
                    if ph.is_empty() {
                        ph.push(next_c);
                        chars.next();
                    }
                    break;
                }
            }

            let val = match ph.as_str() {
                "n" => "\n".to_string(),
                "H" => c.oid.clone(),
                "h" => c.short_oid.clone(),
                "P" => c.parents.join(" "),
                "p" => c.short_parents.join(" "),
                "d" => node.ref_text.clone(),
                "s" => c.summary.clone(),
                "b" => indent_text(&c.body, 4),
                "B" => {
                    let mut b = c.summary.clone();
                    if !c.body.is_empty() {
                        b.push_str("\n\n");
                        b.push_str(&c.body);
                    }
                    indent_text(&b, 4)
                }
                "an" => c.author_name.clone(),
                "ae" => c.author_email.clone(),
                "ad" => format_git_date(c.author_time, c.author_offset),
                "as" => format_git_date_short(c.author_time, c.author_offset),
                "ar" => format_git_date_relative(c.author_time),
                "cn" => c.committer_name.clone(),
                "ce" => c.committer_email.clone(),
                "cd" => format_git_date(c.committer_time, c.committer_offset),
                "cs" => format_git_date_short(c.committer_time, c.committer_offset),
                "cr" => format_git_date_relative(c.committer_time),
                _ => format!("%{}", ph),
            };

            if let Some(m) = modifier {
                if m == '+' {
                    if !val.is_empty() {
                        result.push('\n');
