    let local_ts = timestamp + (offset_minutes as i64 * 60);

    // Unix epoch day calculation
    let secs_per_day = 86400;
    let day_num = (local_ts / secs_per_day) + 719468; // days from 0001-01-01
    let day_of_week = ((local_ts / secs_per_day + 4) % 7 + 7) % 7; // 0 = Sun

