    let off_h = abs_off / 60;
    let off_m = abs_off % 60;

    format!(
        "{} {} {:2} {:02}:{:02}:{:02} {} {}{:02}{:02}",
        days[day_of_week as usize],
        months[(m - 1) as usize],
        d,
        hours,
        mins,
        secs,
        year,
        sign,
        off_h,
        off_m
    )
}

