use crate::graph::GraphData;

pub fn render_svg(graph: &GraphData) {
    let num_rows = graph.nodes.len();
    let mut max_col = 0;
    for b in &graph.branches {
        if b.column < 99 && b.column > max_col {
            max_col = b.column;
        }
    }

    let width = (max_col + 2) * 15;
    let height = (num_rows + 2) * 15;

    println!(
        r#"<svg height="{}" viewBox="0 0 {} {}" width="{}" xmlns="http://www.w3.org/2000/svg">"#,
        height, width, height, width
    );

    // Draw lines between commits / parent connections
    for (i, node) in graph.nodes.iter().enumerate() {
        let cy = (i + 1) * 15;
        let cx = (node.column + 1) * 15;

        // Draw connections to next commit if in same branch
        if i + 1 < num_rows {
            let next_node = &graph.nodes[i + 1];
            let next_cy = (i + 2) * 15;
            let next_cx = (next_node.column + 1) * 15;

            let color = if graph.branches.len() > node.branch_idx {
                &graph.branches[node.branch_idx].svg_color
            } else {
                "gray"
            };

            if cx == next_cx {
                println!(
                    r#"<line stroke="{}" stroke-width="1" x1="{}" x2="{}" y1="{}" y2="{}"/>"#,
                    color, cx, cx, cy, next_cy
                );
            } else {
                let mid_y = (cy + next_cy) as f64 / 2.0;
                let mid_x = (cx + next_cx) as f64 / 2.0;
                println!(
                    r#"<path d="M{},{} L{},{} Q{},{},{},{} Q{},{},{},{} L{},{}" fill="none" stroke="{}" stroke-width="1"/>"#,
                    cx, cy, cx, cy, cx, mid_y, mid_x, mid_y, next_cx, mid_y, next_cx, next_cy, next_cx, next_cy, color
                );
            }
        }
    }

    // Draw circles for commits
    for (i, node) in graph.nodes.iter().enumerate() {
        let cy = (i + 1) * 15;
        let cx = (node.column + 1) * 15;

        let color = if graph.branches.len() > node.branch_idx {
            &graph.branches[node.branch_idx].svg_color
        } else {
            "gray"
        };

        println!(
            r#"<circle cx="{}" cy="{}" fill="{}" r="4" stroke="{}" stroke-width="1"/>"#,
            cx, cy, color, color
        );
    }

    println!("</svg>");
}
