mod args;
mod git;
mod graph;
mod model;
mod render;
mod svg;

use args::{CliArgs, Subcommand};
use git::GitRepo;
use graph::build_graph;
use model::{list_models, load_model};
use render::render_text;
use svg::render_svg;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;
use std::time::Instant;

fn main() {
    let start_time = Instant::now();
    let args = CliArgs::parse();

    match &args.subcommand {
        Subcommand::Model { model: model_opt, list } => {
            if *list {
                let models = list_models();
                println!("{}", models.join("\n"));
                process::exit(0);
            }

            if let Some(m_name) = model_opt {
                // Check if model exists
                if let Err(err) = load_model(m_name) {
                    eprintln!("{}", err);
                    process::exit(1);
                }

                // Open repo
                let repo = match GitRepo::open(&args.path, args.skip_owner_validation) {
                    Ok(r) => r,
                    Err(e) => {
                        eprintln!("{}", e);
                        process::exit(1);
                    }
                };

                let config_path = Path::new(&args.path).join(".git").join("git-graph.toml");
                if let Err(e) = fs::write(&config_path, format!("model = \"{}\"\n", m_name)) {
                    eprintln!("ERROR: Failed to write configuration file: {}", e);
                    process::exit(1);
                }

                eprint!("Branching model set to '{}'", m_name);
                process::exit(0);
            } else {
                // Show current model
                let repo = match GitRepo::open(&args.path, args.skip_owner_validation) {
                    Ok(r) => r,
                    Err(e) => {
                        eprintln!("{}", e);
                        process::exit(1);
                    }
                };

                let config_path = Path::new(&args.path).join(".git").join("git-graph.toml");
                if config_path.exists() {
                    if let Ok(content) = fs::read_to_string(&config_path) {
                        for line in content.lines() {
                            let line = line.trim();
                            if line.starts_with("model =") || line.starts_with("model=") {
                                if let Some(val) = line.split('=').nth(1) {
                                    let clean_val = val.trim().trim_matches('"').trim_matches('\'');
                                    print!("{}", clean_val);
                                    let _ = io::stdout().flush();
                                    process::exit(0);
                                }
                            }
                        }
                    }
                }
                print!("No branching model set");
                let _ = io::stdout().flush();
                process::exit(0);
            }
        }
        Subcommand::Help { cmd } => {
            args::print_long_help();
            process::exit(0);
        }
        Subcommand::None => {}
    }

    // Graph visualization execution
    // Determine model name
    let model_name = if let Some(m) = &args.model {
        m.clone()
    } else {
        let mut found = None;
        let config_path = Path::new(&args.path).join(".git").join("git-graph.toml");
        if config_path.exists() {
            if let Ok(content) = fs::read_to_string(&config_path) {
                for line in content.lines() {
                    let line = line.trim();
                    if line.starts_with("model =") || line.starts_with("model=") {
                        if let Some(val) = line.split('=').nth(1) {
                            found = Some(val.trim().trim_matches('"').trim_matches('\'').to_string());
                        }
                    }
                }
            }
        }
        found.unwrap_or_else(|| "git-flow".to_string())
    };

    let model_config = match load_model(&model_name) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    let repo = match GitRepo::open(&args.path, args.skip_owner_validation) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    let refs = repo.get_refs(args.local_only);
    let commits = match repo.walk_commits() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    let graph_start = Instant::now();
    let graph = build_graph(&commits, &refs, &model_config, args.model.as_deref());
    let graph_duration = graph_start.elapsed();

    if args.debug {
        for b in &graph.branches {
            let start_str = b.start_commit_idx.map(|v| v.to_string()).unwrap_or_else(|| "None".to_string());
            let end_str = b.end_commit_idx.map(|v| v.to_string()).unwrap_or_else(|| "None".to_string());
            let s_str = if b.source_order_group == 9999 { "None".to_string() } else { format!("Some({})", b.source_order_group) };
            let t_str = if b.target_order_group == 9999 { "None".to_string() } else { format!("Some({})", b.target_order_group) };

            eprintln!(
                "{} (col {}) ((Some({}), Some({})))  s: {}, t: {}",
                b.name, b.column, start_str, end_str, s_str, t_str
            );
        }
        let graph_ms = graph_duration.as_secs_f64() * 1000.0;
        eprintln!(
            "Graph construction: {:.1} ms, printing: 0.0 ms ({} commits)",
            graph_ms, graph.nodes.len()
        );
    }

    let use_color = match args.color.as_str() {
        "always" => !args.no_color,
        "never" => false,
        _ => !args.no_color && atty_is_terminal(),
    };

    if args.svg {
        render_svg(&graph);
    } else {
        render_text(&graph, &args, use_color);
    }
}

fn atty_is_terminal() -> bool {
    unsafe {
        libc_isatty(1) != 0
    }
}

extern "C" {
    #[link_name = "isatty"]
    fn libc_isatty(fd: std::os::raw::c_int) -> std::os::raw::c_int;
}
EOF"}

