pub fn get_ansi_color_code(color_name: &str) -> Option<&'static str> {
    match color_name {
        "black" => Some("\x1b[38;5;0m"),
        "red" => Some("\x1b[38;5;1m"),
        "green" => Some("\x1b[38;5;2m"),
