pub fn render_text(
    graph: &GraphData,
    args: &CliArgs,
    use_color: bool,
) {
    let charset = get_charset(&args.style);

    let mut max_col = 0;
    for b in &graph.branches {
        if b.column < 99 && b.column > max_col {
            max_col = b.column;
        }
    }

    let mut nodes = graph.nodes.clone();
    if args.reverse {
        nodes.reverse();
    }

    if let Some(max_c) = args.max_count {
        if nodes.len() > max_c {
            nodes.truncate(max_c);
        }
    }

    let fmt_str = match args.format.as_str() {
        "oneline" | "o" => "%h%d %s",
        "short" | "s" => "commit %H%d%nAuthor: %an <%ae>%n%n    %s%n",
        "medium" | "m" => "commit %H%d%nAuthor: %an <%ae>%nDate:   %ad%n%n    %s%+b%n",
        "full" | "f" => "commit %H%d%nAuthor: %an <%ae>%nCommit: %cn <%ce>%nDate:   %cd%n%n    %s%+b%n",
        other => autre_format(other),
    };

    for node in &nodes {
        let col = node.column;
        let is_merge = node.commit.parents.len() > 1;
        let dot_char = if is_merge { charset.merge_dot } else { charset.commit_dot };

        // Build graph line prefix: 2 spaces per column before dot, 1 leading space
        let mut graph_prefix = String::new();
        for c in 0..=max_col {
            if c == col {
                graph_prefix.push(' ');
                graph_prefix.push_str(dot_char);
                graph_prefix.push_str("  ");
            } else {
                graph_prefix.push_str("   ");
            }
        }

        let formatted_text = format_commit_text(node, fmt_str, use_color, graph);

        println!("{}{}", graph_prefix, formatted_text);
    }
}

fn autre_format(input: &str) -> &str {
    if input.starts_with('s') {
        "commit %H%d%nAuthor: %an <%ae>%n%n    %s%n"
    } else if input.starts_with('m') {
        "commit %H%d%nAuthor: %an <%ae>%nDate:   %ad%n%n    %s%+b%n"
    } else if input.starts_with('f') {
        "commit %H%d%nAuthor: %an <%ae>%nCommit: %cn <%ce>%nDate:   %cd%n%n    %s%+b%n"
    } else if input.starts_with('o') {
        "%h%d %s"
    } else {
        input
    }
}

fn format_commit_text(
    node: &CommitNode,
    fmt: &str,
    use_color: bool,
    graph: &GraphData,
) -> String {
    let c = &node.commit;
    let mut result = String::new();
    let mut chars = fmt.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '%' {
            let mut modifier = None;
            if let Some(&next_c) = chars.peek() {
                if next_c == '+' || next_c == '-' || next_c == ' ' {
                    modifier = Some(next_c);
                    chars.next();
                }
            }

            let mut ph = String::new();
            while let Some(&next_c) = chars.peek() {
                if next_c.is_alphabetic() {
                    ph.push(next_c);
                    chars.next();
                    if ph == "an" || ph == "ae" || ph == "ad" || ph == "as" || ph == "ar"
                        || ph == "cn" || ph == "ce" || ph == "cd" || ph == "cs" || ph == "cr" {
                        break;
                    }
                } else {
                    if ph.is_empty() {
                        ph.push(next_c);
                        chars.next();
                    }
                    break;
                }
            }

            let val = match ph.as_str() {
                "n" => "\n".to_string(),
                "H" => c.oid.clone(),
                "h" => c.short_oid.clone(),
                "P" => c.parents.join(" "),
                "p" => c.short_parents.join(" "),
                "d" => {
                    if node.ref_text.is_empty() {
                        String::new()
                    } else {
                        format!(" {}", node.ref_text)
                    }
                }
                "s" => c.summary.clone(),
                "b" => indent_text(&c.body, 4),
                "B" => {
                    let mut b = c.summary.clone();
                    if !c.body.is_empty() {
                        b.push_str("\n\n");
                        b.push_str(&c.body);
                    }
                    indent_text(&b, 4)
                }
                "an" => c.author_name.clone(),
                "ae" => c.author_email.clone(),
                "ad" => format_git_date(c.author_time, c.author_offset),
                "as" => format_git_date_short(c.author_time, c.author_offset),
                "ar" => format_git_date_relative(c.author_time),
                "cn" => c.committer_name.clone(),
                "ce" => c.committer_email.clone(),
                "cd" => format_git_date(c.committer_time, c.committer_offset),
                "cs" => format_git_date_short(c.committer_time, c.committer_offset),
                "cr" => format_git_date_relative(c.committer_time),
                _ => format!("%{}", ph),
            };

            if let Some(m) = modifier {
                if m == '+' {
                    if !val.is_empty() {
                        result.push('\n');
                        result.push_str(&val);
                    }
                } else if m == '-' {
                    if val.is_empty() {
                        while result.ends_with('\n') {
                            result.pop();
                        }
                    } else {
                        result.push_str(&val);
                    }
                } else if m == ' ' {
                    if !val.is_empty() {
                        result.push(' ');
                        result.push_str(&val);
                    }
                }
            } else {
                result.push_str(&val);
            }
        } else {
            result.push(ch);
        }
    }

    result
}

fn indent_text(text: &str, spaces: usize) -> String {
    let indent = " ".repeat(spaces);
    let mut lines = Vec::new();
    for (i, line) in text.lines().enumerate() {
        if i == 0 {
            lines.push(line.to_string());
        } else {
            lines.push(format!("{}{}", indent, line));
        }
    }
    lines.join("\n")
}
EOF

